#!/usr/bin/env python3
from pathlib import Path

ISSUER=Path('scripts/ci/es80_authenticated_stationary_final_go.py')
SIGNED=Path('scripts/ci/es80_authenticated_stationary_signed_artifact.py')
TEST=Path('scripts/ci/tests/test_es80_authenticated_stationary_signed_artifact.py')

def one(text,old,new,label):
    count=text.count(old)
    if count!=1: raise SystemExit(f'{label}: expected one match, got {count}')
    return text.replace(old,new,1)

s=SIGNED.read_text()
s=one(s,'import hashlib\nimport os\n','import hashlib\nimport hmac\nimport os\n','signed imports')
start=s.index('def _read_intended_device(path: Path, repository_root: Path) -> str:\n')
end=s.index('\n\ndef retain_and_reinspect(',start)
new_reader='''def _read_intended_device(\n    path: Path, repository_root: Path, expected_sha256: str | None = None\n) -> str:\n    expanded = path.expanduser()\n    if (\n        not expanded.is_absolute()\n        or expanded.anchor != os.sep\n        or any(component in ("", ".", "..") for component in expanded.parts[1:])\n    ):\n        raise SignedArtifactError("private intended-device identifier path must be canonical absolute")\n    if (\n        not hasattr(os, "O_NOFOLLOW")\n        or not hasattr(os, "O_DIRECTORY")\n        or os.open not in os.supports_dir_fd\n    ):\n        raise SignedArtifactError("descriptor-bound private intended-device custody is unavailable")\n    try:\n        repository = repository_root.resolve(strict=True)\n        repository_metadata = os.stat(repository)\n    except OSError as error:\n        raise SignedArtifactError("candidate repository privacy boundary is unavailable") from error\n    repository_identity = (repository_metadata.st_dev, repository_metadata.st_ino)\n    cloexec = getattr(os, "O_CLOEXEC", 0)\n    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | cloexec\n    file_flags = os.O_RDONLY | os.O_NOFOLLOW | cloexec\n    parent = None\n    descriptor = None\n    try:\n        parent = os.open(os.sep, directory_flags)\n        for component in expanded.parts[1:-1]:\n            child = os.open(component, directory_flags, dir_fd=parent)\n            metadata = os.fstat(child)\n            if (metadata.st_dev, metadata.st_ino) == repository_identity:\n                os.close(child)\n                raise SignedArtifactError(\n                    "private intended-device identifier must remain outside repository"\n                )\n            os.close(parent)\n            parent = child\n        descriptor = os.open(expanded.parts[-1], file_flags, dir_fd=parent)\n    except OSError as error:\n        raise SignedArtifactError(\n            "private intended-device identifier unavailable through descriptor-bound path custody"\n        ) from error\n    finally:\n        if parent is not None:\n            os.close(parent)\n    try:\n        before = os.fstat(descriptor)\n        if (\n            not stat.S_ISREG(before.st_mode)\n            or stat.S_IMODE(before.st_mode) != 0o600\n            or before.st_uid != os.geteuid()\n            or before.st_nlink != 1\n            or before.st_size < 1\n            or before.st_size > 160\n        ):\n            raise SignedArtifactError("private intended-device identifier custody is invalid")\n        raw = b""\n        while len(raw) <= 160:\n            chunk = os.read(descriptor, 161 - len(raw))\n            if not chunk:\n                break\n            raw += chunk\n        after = os.fstat(descriptor)\n    finally:\n        if descriptor is not None:\n            os.close(descriptor)\n    stable = lambda value: (\n        value.st_dev, value.st_ino, value.st_mode, value.st_uid, value.st_gid,\n        value.st_nlink, value.st_size, value.st_mtime_ns, value.st_ctime_ns\n    )\n    if len(raw) != before.st_size or stable(before) != stable(after):\n        raise SignedArtifactError("private intended-device identifier changed while being read")\n    try:\n        value = raw.decode("utf-8").strip()\n    except UnicodeDecodeError as error:\n        raise SignedArtifactError("private intended-device identifier is not UTF-8") from error\n    if not value or len(value) > 160 or any(character.isspace() for character in value):\n        raise SignedArtifactError("private intended-device identifier is malformed")\n    if expected_sha256 is not None:\n        expected = expected_sha256.lower()\n        if re.fullmatch(r"[0-9a-f]{64}", expected) is None:\n            raise SignedArtifactError("accepted intended-device digest is malformed")\n        actual = hashlib.sha256(value.encode("utf-8")).hexdigest()\n        if not hmac.compare_digest(actual, expected):\n            raise SignedArtifactError(\n                "private intended-device identifier does not match Final GO authority"\n            )\n    return value\n'''
s=s[:start]+new_reader+s[end:]
old='''    repository = candidate_repo.expanduser().resolve(strict=True)\n    intended_device = _read_intended_device(device_file, repository)\n    dependency_sha = _sha_file(repository / "Podfile.lock")\n    if install.get("sourceCommitSHA") != source or install.get("bundleIdentifier") != BUNDLE:\n'''
new='''    repository = candidate_repo.expanduser().resolve(strict=True)\n    expected_device_digest = install.get("intendedDeviceIdentifierSHA256")\n    if not isinstance(expected_device_digest, str):\n        raise SignedArtifactError("private installer subject lacks accepted intended-device digest")\n    intended_device = _read_intended_device(device_file, repository, expected_device_digest)\n    dependency_sha = _sha_file(repository / "Podfile.lock")\n    if install.get("sourceCommitSHA") != source or install.get("bundleIdentifier") != BUNDLE:\n'''
if s.count(old)!=2: raise SystemExit(f'expected two artifact admission matches, got {s.count(old)}')
s=s.replace(old,new)
SIGNED.write_text(s)

i=ISSUER.read_text()
i=one(i,'signed=inspect_signed_artifact(candidate_repo,source,device_file,got,retained_ipa)','artifact_install={**got,"intendedDeviceIdentifierSHA256":dh}\n    signed=inspect_signed_artifact(candidate_repo,source,device_file,artifact_install,retained_ipa)','initial artifact binding')
i=one(i,'post_dh=device_hash(device_file); post_signed=reinspect_signed_artifact(candidate_repo,source,device_file,got,retained_ipa)','post_dh=device_hash(device_file); post_signed=reinspect_signed_artifact(candidate_repo,source,device_file,artifact_install,retained_ipa)','post artifact binding')
ISSUER.write_text(i)

t=TEST.read_text()
t=one(t,'''        return {\n            "sourceCommitSHA": SOURCE,\n            "bundleIdentifier": signed.BUNDLE,\n        }\n''','''        return {\n            "sourceCommitSHA": SOURCE,\n            "bundleIdentifier": signed.BUNDLE,\n            "intendedDeviceIdentifierSHA256": signed._sha_bytes(DEVICE.encode("utf-8")),\n        }\n''','install subject digest')
marker='''    def test_end_to_end_retains_and_reinspects_exact_signed_ipa(self) -> None:\n'''
addition='''    def test_private_device_reader_rejects_symlinked_ancestor(self) -> None:\n        real_parent = self.root / "real-device-parent"\n        real_parent.mkdir()\n        private = real_parent / "device.udid"\n        private.write_text(DEVICE + "\\n", encoding="utf-8")\n        os.chmod(private, 0o600)\n        alias = self.root / "device-parent-alias"\n        alias.symlink_to(real_parent, target_is_directory=True)\n        with self.assertRaises(signed.SignedArtifactError):\n            signed._read_intended_device(\n                alias / "device.udid",\n                self.repo,\n                signed._sha_bytes(DEVICE.encode("utf-8")),\n            )\n\n    def test_private_device_reader_is_bound_to_preaccepted_digest(self) -> None:\n        with self.assertRaises(signed.SignedArtifactError):\n            signed._read_intended_device(self.device, self.repo, "0" * 64)\n\n    def test_retained_artifact_rejects_device_path_retargeted_after_final_go_admission(self) -> None:\n        self.device.write_text("00008101-FFFFFFFFFFFFFFFF", encoding="utf-8")\n        os.chmod(self.device, 0o600)\n        output = self.root / signed.IPA_NAME\n        with mock.patch.dict(os.environ, {"TMPDIR": str(self.root / "tmp")}, clear=False):\n            with self.assertRaises(signed.SignedArtifactError):\n                signed.retain_and_reinspect(\n                    self.repo, SOURCE, self.device, self.install_subject(), output, runner=self.runner\n                )\n        self.assertFalse(output.exists())\n\n'''
t=one(t,marker,addition+marker,'regression insertion')
TEST.write_text(t)
